"""Small hosted surface for native Vibe operations and market data."""

from __future__ import annotations

import hashlib
import json
import os
import re
import shutil
import sqlite3
import threading
import uuid
from contextlib import closing
from datetime import date, datetime, timezone
from pathlib import Path
from typing import Any

from fastapi import Depends, FastAPI, HTTPException, Query, Request
from fastapi.responses import Response
from src.api.security import require_auth
from src.config.paths import get_runs_dir, get_runtime_root, get_uploads_dir

_ACTIVE_STATES = ("queued", "running")
_OPERATION_NAMES = frozenset(
    {
        "backtest",
        "extract_shadow_strategy",
        "run_shadow_backtest",
        "render_shadow_report",
        "scan_shadow_signals",
    }
)
_SHADOW_ID_RE = re.compile(r"^shadow_[0-9a-f]{8}$")
_UPLOAD_ID_RE = re.compile(r"^[0-9a-f]{32}$")
_RUN_ID_RE = re.compile(r"^[A-Za-z0-9_-]{1,128}$")
_SOURCE_ENUM = frozenset({"auto", "tencent", "eastmoney", "local"})
_MARKET_ENUM = frozenset({"china_a", "hk", "us", "crypto"})
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
_RESULT_LIMIT = 2 * 1024 * 1024
_BACKTEST_INPUT_LIMIT = 16 * 1024 * 1024
_BACKTEST_CODE_FILE_LIMIT = 1024
_CONFIG_SECRET_KEY_RE = re.compile(
    r"(?:^|[_-])(?:api[_-]?key|token|secret|password|credential|access[_-]?key|authorization)(?:$|[_-])",
    re.IGNORECASE,
)
_RECOVERY_LOCK = threading.Lock()
_RECOVERED_DATABASES: set[str] = set()


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _ensure_private_file(path: Path) -> None:
    try:
        os.chmod(path, 0o600)
    except OSError:
        # Windows ACLs protect the runtime directory; chmod is advisory there.
        pass


class _OperationStore:
    """Short-transaction SQLite job index under the native private home."""

    def __init__(self) -> None:
        self.path = get_runtime_root() / "mona-operations.sqlite3"

    def _connect(self) -> sqlite3.Connection:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        connection = sqlite3.connect(self.path, timeout=30)
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA busy_timeout = 30000")
        connection.execute(
            """CREATE TABLE IF NOT EXISTS operations (
                operation_id TEXT PRIMARY KEY,
                operation TEXT NOT NULL,
                status TEXT NOT NULL,
                payload_json TEXT NOT NULL,
                references_json TEXT NOT NULL,
                source_json TEXT NOT NULL,
                tool_result_raw TEXT,
                error_category TEXT,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            )"""
        )
        _ensure_private_file(self.path)
        return connection

    def recover_once(self) -> None:
        key = str(self.path.resolve())
        with _RECOVERY_LOCK:
            if key in _RECOVERED_DATABASES:
                return
            with closing(self._connect()) as connection:
                connection.execute(
                    "UPDATE operations SET status='interrupted', updated_at=? "
                    "WHERE status IN ('queued', 'running')",
                    (_now(),),
                )
                connection.commit()
            _RECOVERED_DATABASES.add(key)

    def create(
        self,
        operation_id: str,
        operation: str,
        persisted_payload: dict[str, Any],
        references: dict[str, Any],
        source: dict[str, Any],
    ) -> None:
        with closing(self._connect()) as connection:
            connection.execute("BEGIN IMMEDIATE")
            active = connection.execute(
                "SELECT 1 FROM operations WHERE status IN ('queued','running') LIMIT 1"
            ).fetchone()
            if active is not None:
                connection.rollback()
                raise HTTPException(status_code=409, detail="A native operation is already active")
            now = _now()
            connection.execute(
                "INSERT INTO operations(operation_id,operation,status,payload_json,references_json,"
                "source_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)",
                (
                    operation_id,
                    operation,
                    "queued",
                    json.dumps(persisted_payload, ensure_ascii=False, sort_keys=True),
                    json.dumps(references, ensure_ascii=False, sort_keys=True),
                    json.dumps(source, ensure_ascii=False, sort_keys=True),
                    now,
                    now,
                ),
            )
            connection.commit()

    def update(
        self,
        operation_id: str,
        *,
        status: str | None = None,
        references: dict[str, Any] | None = None,
        raw_result: str | None = None,
        error_category: str | None = None,
    ) -> None:
        fields: list[str] = ["updated_at=?"]
        values: list[Any] = [_now()]
        if status is not None:
            fields.append("status=?")
            values.append(status)
        if references is not None:
            fields.append("references_json=?")
            values.append(json.dumps(references, ensure_ascii=False, sort_keys=True))
        if raw_result is not None:
            fields.append("tool_result_raw=?")
            values.append(raw_result)
        if error_category is not None:
            fields.append("error_category=?")
            values.append(error_category)
        values.append(operation_id)
        with closing(self._connect()) as connection:
            connection.execute(
                f"UPDATE operations SET {', '.join(fields)} WHERE operation_id=?", values
            )
            connection.commit()

    def get(self, operation_id: str) -> dict[str, Any] | None:
        with closing(self._connect()) as connection:
            row = connection.execute(
                "SELECT * FROM operations WHERE operation_id=?", (operation_id,)
            ).fetchone()
        return self._decode(row) if row is not None else None

    def list(self, limit: int) -> list[dict[str, Any]]:
        with closing(self._connect()) as connection:
            rows = connection.execute(
                "SELECT operation_id,operation,status,payload_json,references_json,source_json,"
                "error_category,created_at,updated_at FROM operations "
                "ORDER BY created_at DESC LIMIT ?",
                (limit,),
            ).fetchall()
        return [self._decode(row) for row in rows]

    def active_count(self) -> int:
        with closing(self._connect()) as connection:
            row = connection.execute(
                "SELECT COUNT(*) AS n FROM operations WHERE status IN ('queued','running')"
            ).fetchone()
        return int(row["n"])

    @staticmethod
    def _decode(row: sqlite3.Row) -> dict[str, Any]:
        result: dict[str, Any] = {
            "operation_id": row["operation_id"],
            "operation": row["operation"],
            "status": row["status"],
            "payload": json.loads(row["payload_json"]),
            "references": json.loads(row["references_json"]),
            "source": json.loads(row["source_json"]),
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
            "cancellation_supported": False,
        }
        raw = row["tool_result_raw"] if "tool_result_raw" in row.keys() else None
        if raw is not None:
            result["tool_result_raw"] = raw
            try:
                result["tool_result"] = json.loads(raw)
            except json.JSONDecodeError:
                result["tool_result"] = None
        if row["error_category"] is not None:
            result["error_category"] = row["error_category"]
        return result


def active_operation_count() -> int:
    """Return the number of queued/running native jobs for /mona/activity."""
    store = _OperationStore()
    store.recover_once()
    return store.active_count()


def _source_receipt() -> dict[str, Any]:
    agent_root = Path(__file__).resolve().parents[2]
    receipt_path = agent_root / "mona-source.json"
    if not receipt_path.is_file():
        raise RuntimeError("native source receipt is unavailable")
    receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
    runtime_root = get_runtime_root().resolve()
    instance_id = os.environ.get("MONA_VIBE_INSTANCE_ID", "")
    if not instance_id:
        raise RuntimeError("native instance identity is unavailable")
    return {
        "instance_id": instance_id,
        "data_root_sha256": hashlib.sha256(str(runtime_root).encode()).hexdigest(),
        **receipt,
    }


def _valid_iso_date(value: Any, field: str) -> str:
    if not isinstance(value, str) or not _DATE_RE.fullmatch(value):
        raise HTTPException(status_code=422, detail=f"{field} must be YYYY-MM-DD")
    try:
        date.fromisoformat(value)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=f"{field} must be a valid date") from exc
    return value


def _date_range(payload: dict[str, Any]) -> None:
    start = payload.get("window_start")
    end = payload.get("window_end")
    if start is not None:
        _valid_iso_date(start, "window_start")
    if end is not None:
        _valid_iso_date(end, "window_end")
    if start and end and start > end:
        raise HTTPException(status_code=422, detail="window_start must not be after window_end")


def _strict_int(payload: dict[str, Any], field: str, minimum: int, maximum: int) -> None:
    if field not in payload:
        return
    value = payload[field]
    if type(value) is not int or not minimum <= value <= maximum:
        raise HTTPException(status_code=422, detail=f"{field} must be an integer in [{minimum}, {maximum}]")


def _resolve_run(run_id: Any) -> Path:
    if not isinstance(run_id, str) or not _RUN_ID_RE.fullmatch(run_id):
        raise HTTPException(status_code=422, detail="run_id must be a bare native run identifier")
    try:
        from src.tools.path_utils import safe_run_id

        run_root = get_runs_dir().resolve(strict=True)
        entry = run_root / run_id
        if _is_link(entry):
            raise ValueError("run_id resolves through a link")
        candidate = safe_run_id(run_id).resolve(strict=True)
        private_root = get_runs_dir().resolve(strict=True)
        if (
            not candidate.is_dir()
            or candidate.parent != private_root
            or not candidate.is_relative_to(private_root)
        ):
            raise ValueError("run is outside the private runtime runs directory")
        return candidate
    except (OSError, RuntimeError, ValueError) as exc:
        raise HTTPException(status_code=404, detail="run_id was not found in the private runtime") from exc


def _is_link(path: Path) -> bool:
    return path.is_symlink() or bool(getattr(path, "is_junction", lambda: False)())


def _contains_credentials(value: Any) -> bool:
    if isinstance(value, dict):
        return any(
            _CONFIG_SECRET_KEY_RE.search(str(key)) or _contains_credentials(item)
            for key, item in value.items()
        )
    if isinstance(value, list):
        return any(_contains_credentials(item) for item in value)
    return False


def _read_bounded(path: Path, maximum: int, description: str) -> bytes:
    with path.open("rb") as stream:
        content = stream.read(maximum + 1)
    if len(content) > maximum:
        raise HTTPException(status_code=413, detail=f"{description} exceeds the input limit")
    return content


def _copy_versioned_run(input_run_id: str, input_run_dir: Path) -> tuple[str, Path]:
    """Copy only validated config/code inputs to a new private run directory."""
    private_root = get_runs_dir().resolve(strict=True)
    source = input_run_dir.resolve(strict=True)
    if _is_link(input_run_dir) or source.parent != private_root:
        raise HTTPException(status_code=422, detail="input run is not a direct private run directory")
    config = source / "config.json"
    code = source / "code"
    if _is_link(config) or not config.is_file() or _is_link(code) or not code.is_dir():
        raise HTTPException(status_code=422, detail="input run must contain config.json and a code directory")
    if config.stat().st_size > 1024 * 1024:
        raise HTTPException(status_code=413, detail="input config exceeds 1 MiB")
    config_bytes = _read_bounded(config, 1024 * 1024, "input config")
    try:
        parsed_config = json.loads(config_bytes)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise HTTPException(status_code=422, detail="input config.json is invalid") from exc
    if not isinstance(parsed_config, dict) or _contains_credentials(parsed_config):
        raise HTTPException(status_code=422, detail="input config must not contain credential fields")

    code_files: list[tuple[Path, Path, int]] = []
    total_size = len(config_bytes)
    for path in sorted(code.rglob("*")):
        if _is_link(path):
            raise HTTPException(status_code=422, detail="input code may not contain symlinks or junctions")
        relative = path.relative_to(code)
        if any(part.lower() in {"__pycache__", ".cache", "cache"} for part in relative.parts):
            continue
        if path.suffix.lower() in {".pyc", ".pyo"}:
            continue
        resolved = path.resolve(strict=True)
        if not resolved.is_relative_to(source) or not resolved.is_relative_to(code.resolve(strict=True)):
            raise HTTPException(status_code=422, detail="input code escapes the private run directory")
        if path.is_dir():
            continue
        if not path.is_file():
            raise HTTPException(status_code=422, detail="input code contains an unsupported filesystem entry")
        name = path.name.lower()
        if (
            name == ".env"
            or name.startswith((".env.", "credentials", "secrets"))
            or path.suffix.lower() in {".pem", ".key", ".p12", ".pfx"}
        ):
            raise HTTPException(status_code=422, detail="input code must not contain credential files")
        size = path.stat().st_size
        total_size += size
        if total_size > _BACKTEST_INPUT_LIMIT:
            raise HTTPException(status_code=413, detail="backtest config and code exceed 16 MiB")
        code_files.append((path, relative, size))
        if len(code_files) > _BACKTEST_CODE_FILE_LIMIT:
            raise HTTPException(status_code=413, detail="backtest code exceeds 1024 files")
    if not any(relative.as_posix() == "signal_engine.py" for _, relative, _ in code_files):
        raise HTTPException(status_code=422, detail="input code/signal_engine.py is required")

    target: Path | None = None
    run_id = ""
    for _ in range(3):
        run_id = f"mona-{uuid.uuid4().hex}"
        candidate = private_root / run_id
        try:
            candidate.mkdir()
            target = candidate
            break
        except FileExistsError:
            continue
    if target is None:
        raise HTTPException(status_code=503, detail="could not allocate a unique backtest run")
    try:
        (target / "config.json").write_bytes(config_bytes)
        target_code = target / "code"
        target_code.mkdir()
        for source_file, relative, expected_size in code_files:
            content = _read_bounded(source_file, expected_size, "input code file")
            if len(content) != expected_size:
                raise OSError("input code changed while it was being copied")
            destination = target_code / relative
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_bytes(content)
        from src.tools.path_utils import safe_run_id

        if safe_run_id(run_id).resolve(strict=True) != target.resolve(strict=True):
            raise ValueError("allocated run is outside the native run allowlist")
        return run_id, target.resolve(strict=True)
    except Exception:
        resolved_target = target.resolve(strict=True)
        if resolved_target.parent == private_root and resolved_target.name == run_id:
            shutil.rmtree(resolved_target, ignore_errors=True)
        raise


def _resolve_upload(upload_id: Any) -> Path:
    if not isinstance(upload_id, str) or not _UPLOAD_ID_RE.fullmatch(upload_id):
        raise HTTPException(status_code=422, detail="upload_id must be a 32-character upload identifier")
    root = get_uploads_dir().resolve(strict=False)
    matches = [
        path for suffix in (".csv", ".xls", ".xlsx")
        for path in root.glob(f"{upload_id}{suffix}")
        if path.is_file() and not path.is_symlink()
    ]
    resolved: list[Path] = []
    for path in matches:
        try:
            candidate = path.resolve(strict=True)
            if candidate.is_relative_to(root):
                resolved.append(candidate)
        except OSError:
            continue
    if len(resolved) != 1:
        raise HTTPException(status_code=404, detail="upload_id was not found in private uploads")
    return resolved[0]


def _validate_payload(payload: dict[str, Any]) -> tuple[str, dict[str, Any], dict[str, Any]]:
    operation = payload.get("operation")
    if not isinstance(operation, str) or operation not in _OPERATION_NAMES:
        raise HTTPException(status_code=422, detail="unsupported native operation")
    schemas: dict[str, tuple[set[str], set[str]]] = {
        "backtest": ({"operation", "run_id"}, set()),
        "extract_shadow_strategy": ({"operation", "upload_id"}, {"min_support", "max_rules"}),
        "run_shadow_backtest": ({"operation", "shadow_id"}, {
            "window_start", "window_end", "markets", "source", "per_market_count", "upload_id",
        }),
        "render_shadow_report": ({"operation", "shadow_id"}, {
            "window_start", "window_end", "include_today_signals", "upload_id",
        }),
        "scan_shadow_signals": ({"operation", "shadow_id"}, {"date", "per_market", "source"}),
    }
    required, optional = schemas[operation]
    keys = set(payload)
    if not required <= keys or keys - required - optional:
        raise HTTPException(status_code=422, detail="operation fields do not match the native tool contract")

    clean = dict(payload)
    references: dict[str, Any] = {}
    if operation == "backtest":
        input_run_id = clean["run_id"]
        run_path = _resolve_run(input_run_id)
        references["input_run_id"] = input_run_id
        clean = {
            "operation": operation,
            "input_run_id": input_run_id,
            "_input_run_dir": str(run_path),
        }
    else:
        shadow_id = clean.get("shadow_id")
        if operation != "extract_shadow_strategy":
            if not isinstance(shadow_id, str) or not _SHADOW_ID_RE.fullmatch(shadow_id):
                raise HTTPException(status_code=422, detail="shadow_id is invalid")
            references["shadow_id"] = shadow_id
        if "upload_id" in clean:
            upload_path = _resolve_upload(clean["upload_id"])
            references["upload_id"] = clean["upload_id"]
            clean["_journal_path"] = str(upload_path)
        if operation == "extract_shadow_strategy":
            references["upload_id"] = clean["upload_id"]
            _strict_int(clean, "min_support", 1, 1000)
            _strict_int(clean, "max_rules", 1, 50)
        if operation in {"run_shadow_backtest", "render_shadow_report"}:
            _date_range(clean)
        if operation == "run_shadow_backtest":
            markets = clean.get("markets")
            if "markets" in clean and (
                not isinstance(markets, list)
                or not markets
                or any(not isinstance(value, str) or value not in _MARKET_ENUM for value in markets)
                or len(set(markets)) != len(markets)
            ):
                raise HTTPException(status_code=422, detail="markets contains an unsupported market")
            if "source" in clean and (
                not isinstance(clean["source"], str) or clean["source"] not in _SOURCE_ENUM
            ):
                raise HTTPException(status_code=422, detail="source is not supported")
            _strict_int(clean, "per_market_count", 1, 100)
        elif operation == "scan_shadow_signals":
            if "date" in clean:
                _valid_iso_date(clean["date"], "date")
            if "source" in clean and (
                not isinstance(clean["source"], str) or clean["source"] not in _SOURCE_ENUM
            ):
                raise HTTPException(status_code=422, detail="source is not supported")
            _strict_int(clean, "per_market", 1, 100)
        elif operation == "render_shadow_report":
            if "include_today_signals" in clean and type(clean["include_today_signals"]) is not bool:
                raise HTTPException(status_code=422, detail="include_today_signals must be boolean")

    return operation, clean, references


def _tool_call(operation: str, payload: dict[str, Any]) -> tuple[str, dict[str, Any]]:
    from src.tools.backtest_tool import BacktestTool
    from src.tools.shadow_account_tool import (
        ExtractShadowStrategyTool,
        RenderShadowReportTool,
        RunShadowBacktestTool,
        ScanShadowSignalsTool,
    )

    references: dict[str, Any] = {}
    if operation == "backtest":
        references["run_id"] = payload["run_id"]
        raw = BacktestTool().execute(run_dir=payload["_run_dir"])
    else:
        args = {key: value for key, value in payload.items() if key != "operation"}
        args.pop("upload_id", None)
        journal_path = args.pop("_journal_path", None)
        if journal_path is not None:
            args["journal_path"] = journal_path
        before: set[str] = set()
        shadow_id = args.get("shadow_id")
        if shadow_id and operation in {"run_shadow_backtest", "render_shadow_report"}:
            from src.shadow_account.storage import runs_dir

            directory = runs_dir(shadow_id)
            before = {path.name for path in directory.iterdir() if path.is_dir()}
        tool_type = {
            "extract_shadow_strategy": ExtractShadowStrategyTool,
            "run_shadow_backtest": RunShadowBacktestTool,
            "render_shadow_report": RenderShadowReportTool,
            "scan_shadow_signals": ScanShadowSignalsTool,
        }[operation]
        raw = tool_type().execute(**args)
        if shadow_id:
            references["shadow_id"] = shadow_id
        if operation in {"run_shadow_backtest", "render_shadow_report"} and shadow_id:
            after = {path.name for path in runs_dir(shadow_id).iterdir() if path.is_dir()}
            references["run_ids"] = sorted(after - before)
    if len(raw.encode("utf-8")) > _RESULT_LIMIT:
        raise ValueError("tool_result_too_large")
    return raw, references


def _run_operation(
    store: _OperationStore,
    operation_id: str,
    operation: str,
    payload: dict[str, Any],
    initial_references: dict[str, Any],
) -> None:
    store.update(operation_id, status="running")
    try:
        raw, tool_references = _tool_call(operation, payload)
        try:
            parsed = json.loads(raw)
        except json.JSONDecodeError as exc:
            raise ValueError("invalid_tool_json") from exc
        if not isinstance(parsed, dict):
            raise ValueError("invalid_tool_result")
        references = dict(initial_references)
        references.update(tool_references)
        references.update(_result_references(operation, parsed))
        failed = parsed.get("status") == "error" or parsed.get("ok") is False
        store.update(
            operation_id,
            status="failed" if failed else "completed",
            references=references,
            raw_result=raw,
            error_category="native_tool_error" if failed else None,
        )
    except Exception as exc:  # persist the category only, never traceback or secrets
        category = str(exc) if str(exc) in {
            "tool_result_too_large", "invalid_tool_json", "invalid_tool_result"
        } else type(exc).__name__
        store.update(operation_id, status="failed", error_category=category)


def _result_references(operation: str, parsed: dict[str, Any]) -> dict[str, Any]:
    if operation == "extract_shadow_strategy" and isinstance(parsed.get("shadow_id"), str):
        return {"shadow_id": parsed["shadow_id"]}
    return {}


def _queue_operation(
    store: _OperationStore,
    operation: str,
    worker_payload: dict[str, Any],
    persisted_payload: dict[str, Any],
    references: dict[str, Any],
) -> dict[str, Any]:
    operation_id = uuid.uuid4().hex
    source = _source_receipt()
    if operation == "backtest":
        try:
            run_id, run_dir = _copy_versioned_run(
                worker_payload["input_run_id"], Path(worker_payload["_input_run_dir"])
            )
        except HTTPException:
            raise
        except (OSError, RuntimeError, ValueError) as exc:
            raise HTTPException(status_code=422, detail="input run could not be safely copied") from exc
        worker_payload = {
            "operation": "backtest",
            "input_run_id": worker_payload["input_run_id"],
            "run_id": run_id,
            "_run_dir": str(run_dir),
        }
        references = {"input_run_id": worker_payload["input_run_id"], "run_id": run_id}
        persisted_payload = {
            "operation": operation,
            "input_run_id": worker_payload["input_run_id"],
            "run_id": run_id,
        }
    try:
        store.create(operation_id, operation, persisted_payload, references, source)
    except Exception:
        if operation == "backtest":
            run_path = Path(worker_payload["_run_dir"]).resolve(strict=True)
            private_root = get_runs_dir().resolve(strict=True)
            if run_path.parent == private_root and run_path.name == worker_payload["run_id"]:
                shutil.rmtree(run_path, ignore_errors=True)
        raise
    worker = threading.Thread(
        target=_run_operation,
        args=(store, operation_id, operation, worker_payload, references),
        name=f"mona-operation-{operation_id[:8]}",
        daemon=True,
    )
    try:
        worker.start()
    except Exception as exc:
        store.update(operation_id, status="failed", error_category=type(exc).__name__)
        raise HTTPException(status_code=503, detail="Native operation could not be queued") from exc
    record = store.get(operation_id)
    assert record is not None
    return record


def _market_data_request(payload: dict[str, Any]) -> tuple[str, str, str, str, str]:
    allowed = {"symbol", "start_date", "end_date", "interval", "source"}
    if set(payload) - allowed or not {"symbol", "start_date", "end_date", "interval"} <= set(payload):
        raise HTTPException(status_code=422, detail="market-data fields do not match the contract")
    symbol = payload["symbol"]
    if not isinstance(symbol, str) or not re.fullmatch(r"\d{6}\.(?:SH|SZ|BJ)", symbol):
        raise HTTPException(status_code=422, detail="symbol must be a six-digit A-share code with exchange suffix")
    start = _valid_iso_date(payload["start_date"], "start_date")
    end = _valid_iso_date(payload["end_date"], "end_date")
    if start > end:
        raise HTTPException(status_code=422, detail="start_date must not be after end_date")
    from backtest.runner import _VALID_INTERVALS

    interval = payload["interval"]
    if not isinstance(interval, str) or interval not in _VALID_INTERVALS:
        raise HTTPException(status_code=422, detail="interval is not supported by the native market-data tool")
    source = payload.get("source")
    if source is None:
        source = "tencent" if interval == "1D" and not symbol.endswith(".BJ") else "eastmoney"
    if not isinstance(source, str) or source not in {"tencent", "eastmoney"}:
        raise HTTPException(status_code=422, detail="source must be tencent or eastmoney")
    if source == "tencent" and (interval != "1D" or symbol.endswith(".BJ")):
        raise HTTPException(status_code=422, detail="Tencent serves daily SH/SZ A-share bars only")
    if source == "eastmoney":
        from backtest.loaders.eastmoney_client import KLT_BY_INTERVAL

        if interval not in KLT_BY_INTERVAL:
            raise HTTPException(status_code=422, detail="Eastmoney does not support the requested interval")
    return symbol, start, end, interval, source


def register_mona_operations(app: FastAPI) -> None:
    """Register hosted-only operation jobs and a narrow native market-data read."""
    if os.environ.get("VIBE_TRADING_HOSTED") != "1":
        return
    store = _OperationStore()
    store.recover_once()

    @app.post("/mona/operations", status_code=202, dependencies=[Depends(require_auth)])
    async def create_mona_operation(payload: dict[str, Any]) -> dict[str, Any]:
        operation, clean, references = _validate_payload(payload)
        return _queue_operation(store, operation, clean, dict(payload), references)

    @app.get("/mona/operations", dependencies=[Depends(require_auth)])
    async def list_mona_operations(limit: int = Query(50, ge=1, le=200)) -> dict[str, Any]:
        return {"operations": store.list(limit), "active": store.active_count()}

    @app.get("/mona/operations/{operation_id}", dependencies=[Depends(require_auth)])
    async def get_mona_operation(operation_id: str) -> dict[str, Any]:
        if not re.fullmatch(r"[0-9a-f]{32}", operation_id):
            raise HTTPException(status_code=404, detail="Operation not found")
        record = store.get(operation_id)
        if record is None:
            raise HTTPException(status_code=404, detail="Operation not found")
        return record

    @app.get("/mona/market-data", dependencies=[Depends(require_auth)])
    async def get_mona_market_data(
        request: Request,
        symbol: str,
        start_date: str,
        end_date: str,
        interval: str,
        source: str | None = None,
    ) -> Response:
        allowed_query = {"symbol", "start_date", "end_date", "interval", "source"}
        query = request.query_params
        if set(query.keys()) - allowed_query or any(
            len(query.getlist(key)) != 1 for key in query.keys()
        ):
            raise HTTPException(status_code=422, detail="market-data query fields do not match the contract")
        symbol, start, end, interval_token, actual_source = _market_data_request(
            {
                "symbol": symbol,
                "start_date": start_date,
                "end_date": end_date,
                "interval": interval,
                **({"source": source} if source is not None else {}),
            }
        )
        from src.tools.market_data_tool import MarketDataTool

        raw = MarketDataTool().execute(
            codes=[symbol],
            start_date=start,
            end_date=end,
            interval=interval_token,
            source=actual_source,
            max_rows=0,
        )
        try:
            parsed = json.loads(raw)
        except json.JSONDecodeError:
            return Response(content=raw, status_code=502, media_type="application/json")
        failed = isinstance(parsed, dict) and parsed.get("status") == "error"
        return Response(content=raw, status_code=502 if failed else 200, media_type="application/json")
